import { QRCodeSVG } from "qrcode.react";
import { Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { trpc } from "@/lib/trpc";
import { Button } from "@/components/ui/button";
import { PlanManager, PrivacyControls } from "@/components/SettingsControls";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { toast } from "sonner";
import { ArrowDownRight, ArrowUpRight, Bot, CalendarClock, Check, CheckCircle2, ChevronRight, CircleAlert, CircleDollarSign, CircleUserRound, ClipboardCheck, Download, Pencil, Trash2, HeartHandshake, Inbox, Loader2, Megaphone, MoreHorizontal, Plus, RefreshCw, Search, Send, Settings2, Sparkles, Target, Users, WalletCards, X } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { Link, useLocation, useRoute } from "wouter";

const customerQuery = { page: 1, pageSize: 50 };
const money = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" });
const number = new Intl.NumberFormat("pt-BR");
const date = (value: Date | string | null | undefined) => value ? new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "short", year: "numeric" }).format(new Date(value)) : "Sem registro";
const dateTime = (value: Date | string | null | undefined) => value ? new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }).format(new Date(value)) : "—";
const statusName = { active: "Ativo", at_risk: "Em risco", inactive: "Inativo", pending: "Pendente", contacted: "Contatado", responded: "Respondeu", recovered: "Recuperado", lost: "Perdido", draft: "Rascunho", scheduled: "Agendada", sent: "Enviada", paused: "Pausada", open: "Aberta", done: "Concluída", low: "Baixa", medium: "Média", high: "Alta" } as const;
const statusStyle: Record<string, string> = { active: "bg-[#e5f6d7] text-[#38662f]", at_risk: "bg-[#fff2d5] text-[#96630b]", inactive: "bg-[#fbe2e2] text-[#a13d3d]", pending: "bg-[#edf1ed] text-[#5c6c60]", contacted: "bg-[#e3f0fb] text-[#396786]", responded: "bg-[#ede6ff] text-[#694ea1]", recovered: "bg-[#e2f5d6] text-[#38672c]", lost: "bg-[#f3e6e6] text-[#965050]", draft: "bg-[#eef0ee] text-[#5d6b61]", scheduled: "bg-[#fef0d3] text-[#89600f]", sent: "bg-[#e3f1fb] text-[#316583]", paused: "bg-[#f5e8e8] text-[#965050]", open: "bg-[#fff0d6] text-[#8d6010]", done: "bg-[#e3f4da] text-[#37682c]", high: "bg-[#fbe3e3] text-[#a24242]", medium: "bg-[#fff1d5] text-[#96630b]", low: "bg-[#e6f1fb] text-[#396786]" };

function errorMessage(error: unknown) { return error instanceof Error ? error.message : "Não foi possível concluir esta ação."; }
function Status({ value }: { value: keyof typeof statusName | string }) { return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.08em] ${statusStyle[value] ?? "bg-slate-100 text-slate-600"}`}>{statusName[value as keyof typeof statusName] ?? value}</span>; }
function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="hl-eyebrow">{eyebrow}</p><h1 className="mt-1.5 text-[28px] font-semibold tracking-[-0.055em] text-[#18221a] sm:text-[32px]">{title}</h1><p className="mt-1 text-sm text-[#748077]">{description}</p></div>{action && <div className="shrink-0">{action}</div>}</div>; }
function Empty({ icon: Icon, title, description, action }: { icon: typeof Inbox; title: string; description: string; action?: React.ReactNode }) { return <div className="hl-card flex min-h-[260px] flex-col items-center justify-center px-6 py-10 text-center"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#eff4eb] text-[#54755b]"><Icon className="h-5 w-5" /></div><h3 className="mt-4 font-semibold tracking-[-0.02em] text-[#1b271e]">{title}</h3><p className="mt-1 max-w-sm text-sm leading-6 text-[#748077]">{description}</p>{action && <div className="mt-5">{action}</div>}</div>; }
function MiniKpi({ label, value, hint, tone = "green" }: { label: string; value: string; hint: string; tone?: "green" | "amber" | "red" | "ink" }) { const tones = { green: "bg-[#e5f6d7] text-[#426e32]", amber: "bg-[#fff2d9] text-[#8e6314]", red: "bg-[#fbe6e6] text-[#a13e3e]", ink: "bg-[#e9efea] text-[#354c39]" }; return <div className="hl-card p-5"><div className="flex items-start justify-between"><p className="text-xs font-medium text-[#6f7d73]">{label}</p><span className={`grid h-7 w-7 place-items-center rounded-lg ${tones[tone]}`}><Sparkles className="h-3.5 w-3.5" /></span></div><p className="mt-5 text-2xl font-semibold tracking-[-0.05em] text-[#19241b]">{value}</p><p className="mt-1.5 text-[11px] text-[#819087]">{hint}</p></div>; }

export function DashboardPage() {
  const report = trpc.reports.overview.useQuery();
  const [, navigate] = useLocation();
  if (report.isLoading) return <DashboardSkeleton />;
  const data = report.data;
  if (!data) return <div className="hl-page"><Empty icon={CircleAlert} title="Painel indisponível" description="Não foi possível carregar os indicadores da organização. Tente atualizar." /></div>;
  const { metrics } = data;
  const audienceData = [{ name: "Ativos", value: metrics.active, color: "#80a95a" }, { name: "Em risco", value: metrics.atRisk, color: "#efbe5d" }, { name: "Inativos", value: metrics.inactive, color: "#d87878" }];
  const totalCustomers = Math.max(1, metrics.active + metrics.atRisk + metrics.inactive);
  return <div className="hl-page hl-fade-in">
    <PageHeader eyebrow="Visão geral" title="O pulso da sua retenção." description="Veja onde sua receita está em risco e aja antes que o cliente suma." action={<Button onClick={() => navigate("/app/clientes")} className="h-10 rounded-xl bg-[#1a3021] px-4 text-xs font-semibold hover:bg-[#2d4935]"><Plus className="mr-1.5 h-4 w-4" />Novo cliente</Button>} />
    <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      <MiniKpi label="Clientes ativos" value={number.format(metrics.active)} hint={`${Math.round(metrics.active / totalCustomers * 100)}% da sua base`} />
      <MiniKpi label="Precisam de atenção" value={number.format(metrics.atRisk)} hint="Entre 30 e 59 dias sem compra" tone="amber" />
      <MiniKpi label="Já estão inativos" value={number.format(metrics.inactive)} hint="Priorize a recuperação hoje" tone="red" />
      <MiniKpi label="Receita recuperada" value={money.format(metrics.recoveredRevenue)} hint={`${number.format(metrics.recovered)} clientes recuperados`} tone="ink" />
    </section>
    <section className="mt-5 grid gap-5 xl:grid-cols-[1.28fr_0.72fr]">
      <div className="hl-card p-5 sm:p-6"><div className="flex items-start justify-between"><div><p className="text-sm font-semibold tracking-[-0.02em] text-[#1b271e]">Saúde da carteira</p><p className="mt-1 text-xs text-[#78857b]">Classificação pela última compra registrada.</p></div><button onClick={() => navigate("/app/recuperacao")} className="text-xs font-semibold text-[#47744e] hover:text-[#1f4930]">Ver recuperação <ChevronRight className="inline h-3.5 w-3.5" /></button></div>
        <div className="mt-4 h-[230px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={audienceData} barSize={34}><CartesianGrid vertical={false} stroke="#edf0eb" /><XAxis dataKey="name" tick={{ fontSize: 11, fill: "#7a887e" }} axisLine={false} tickLine={false} /><YAxis allowDecimals={false} tick={{ fontSize: 11, fill: "#7a887e" }} axisLine={false} tickLine={false} /><Tooltip cursor={{ fill: "#f6f8f4" }} contentStyle={{ borderRadius: 12, border: "1px solid #e4e9e3", fontSize: 12 }} /><Bar dataKey="value" radius={[8, 8, 2, 2]}>{audienceData.map(entry => <Cell key={entry.name} fill={entry.color} />)}</Bar></BarChart></ResponsiveContainer></div>
      </div>
      <div className="hl-card p-5 sm:p-6"><p className="text-sm font-semibold tracking-[-0.02em] text-[#1b271e]">Cobertura de automação</p><p className="mt-1 text-xs text-[#78857b]">Recupere rotina sem perder o toque humano.</p><div className="mt-6 flex items-center gap-5"><div className="h-[124px] w-[124px]"><ResponsiveContainer><PieChart><Pie data={audienceData} dataKey="value" innerRadius={38} outerRadius={57} paddingAngle={3} stroke="none">{audienceData.map(entry => <Cell key={entry.name} fill={entry.color} />)}</Pie></PieChart></ResponsiveContainer></div><div className="space-y-3">{audienceData.map(item => <div key={item.name} className="flex items-center gap-2"><span className="h-2 w-2 rounded-full" style={{ background: item.color }} /><span className="text-xs text-[#627066]">{item.name}</span><strong className="ml-auto text-xs text-[#1b271e]">{number.format(item.value)}</strong></div>)}</div></div><div className="mt-5 rounded-xl bg-[#f4f7f1] p-3.5"><p className="text-xs font-semibold text-[#355a3c]">{metrics.pendingTasks} follow-ups aguardando ação</p><p className="mt-1 text-[11px] leading-4 text-[#768379]">A automação abre tarefas para que ninguém fique sem resposta.</p></div></div>
    </section>
    <section className="mt-5 grid gap-5 xl:grid-cols-2"><RiskList title="Clientes em risco" customers={data.atRisk} tone="amber" onOpen={() => navigate("/app/clientes")} /><RiskList title="Inativos com maior potencial" customers={data.inactive} tone="red" onOpen={() => navigate("/app/recuperacao")} /></section>
    <section className="mt-5 grid gap-4 md:grid-cols-3"><div className="rounded-2xl bg-[#1a3021] p-5 text-white"><div className="flex items-center justify-between"><Target className="h-5 w-5 text-[#d8ff70]" /><span className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#aac1ae]">Campanhas</span></div><p className="mt-6 text-2xl font-semibold tracking-[-0.05em]">{number.format(metrics.campaigns)}</p><p className="mt-1 text-xs text-[#bbcbbe]">campanhas criadas</p></div><div className="hl-card p-5"><div className="flex items-center justify-between"><Send className="h-5 w-5 text-[#537b5a]" /><span className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#829087]">WhatsApp</span></div><p className="mt-6 text-2xl font-semibold tracking-[-0.05em] text-[#1b271e]">{number.format(metrics.sentMessages)}</p><p className="mt-1 text-xs text-[#78857b]">mensagens enviadas</p></div><div className="hl-card p-5"><div className="flex items-center justify-between"><ClipboardCheck className="h-5 w-5 text-[#537b5a]" /><span className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#829087]">Respostas</span></div><p className="mt-6 text-2xl font-semibold tracking-[-0.05em] text-[#1b271e]">{number.format(metrics.replies)}</p><p className="mt-1 text-xs text-[#78857b]">interações registradas</p></div></section>
  </div>;
}

function DashboardSkeleton() { return <div className="hl-page"><div className="h-20 w-72 animate-pulse rounded-xl bg-[#e9eee7]" /><div className="mt-6 grid gap-4 md:grid-cols-4">{[1,2,3,4].map(i => <div key={i} className="h-36 animate-pulse rounded-2xl bg-[#e9eee7]" />)}</div></div>; }
function RiskList({ title, customers, tone, onOpen }: { title: string; customers: Array<{ id: number; name: string; totalSpent: string; lastPurchaseAt: Date | null }>; tone: "amber" | "red"; onOpen: () => void }) { return <div className="hl-card overflow-hidden"><div className="flex items-center justify-between border-b border-[#edf0eb] px-5 py-4"><div><p className="text-sm font-semibold tracking-[-0.02em] text-[#1b271e]">{title}</p><p className="mt-0.5 text-[11px] text-[#77847a]">Ordenado pelo valor histórico</p></div><button onClick={onOpen} className="text-xs font-semibold text-[#47744e]">Ver todos</button></div>{customers.length ? <div>{customers.slice(0, 4).map(customer => <div key={customer.id} className="flex items-center gap-3 border-b border-[#f0f2ee] px-5 py-3 last:border-0"><div className={`grid h-8 w-8 place-items-center rounded-full text-[11px] font-bold ${tone === "amber" ? "bg-[#fff1d7] text-[#946111]" : "bg-[#f9e4e4] text-[#a14242]"}`}>{customer.name.slice(0, 2).toUpperCase()}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold text-[#27342a]">{customer.name}</p><p className="mt-0.5 text-[10px] text-[#7a877d]">Última compra: {date(customer.lastPurchaseAt)}</p></div><p className="text-xs font-semibold text-[#344b39]">{money.format(Number(customer.totalSpent))}</p></div>)}</div> : <div className="px-5 py-10 text-center text-xs text-[#7b897e]">Nenhum cliente neste grupo agora.</div>}</div>; }

export function CustomersPage() {
  const [search, setSearch] = useState(""); const [status, setStatus] = useState<"active" | "at_risk" | "inactive" | undefined>(); const [open, setOpen] = useState(false);
  const input = useMemo(() => ({ ...customerQuery, query: search || undefined, status }), [search, status]);
  const customers = trpc.customers.list.useQuery(input); const utils = trpc.useUtils(); const [, navigate] = useLocation();
  const refresh = trpc.customers.refreshStatuses.useMutation({ onSuccess: () => { toast.success("Classificação atualizada."); utils.customers.list.invalidate(); }, onError: e => toast.error(errorMessage(e)) });
  return <div className="hl-page hl-fade-in"><PageHeader eyebrow="Base de clientes" title="Quem precisa da sua atenção?" description="Classifique a carteira pela última compra e mantenha o relacionamento vivo." action={<div className="flex gap-2"><Button variant="outline" onClick={() => refresh.mutate()} disabled={refresh.isPending} className="h-10 rounded-xl bg-white text-xs"><RefreshCw className={`mr-1.5 h-3.5 w-3.5 ${refresh.isPending ? "animate-spin" : ""}`} />Atualizar risco</Button><CustomerDialog open={open} setOpen={setOpen} /></div>} />
    <div className="hl-card overflow-hidden"><div className="flex flex-col gap-3 border-b border-[#ebefea] p-4 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-[#829087]" /><Input value={search} onChange={e => setSearch(e.target.value)} placeholder="Buscar por nome, telefone ou e-mail" className="h-10 rounded-xl border-[#e3e9e2] pl-9 text-xs" /></div><Select value={status ?? "all"} onValueChange={value => setStatus(value === "all" ? undefined : value as "active" | "at_risk" | "inactive")}><SelectTrigger className="h-10 w-full rounded-xl text-xs sm:w-[165px]"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todos os status</SelectItem><SelectItem value="active">Ativos</SelectItem><SelectItem value="at_risk">Em risco</SelectItem><SelectItem value="inactive">Inativos</SelectItem></SelectContent></Select></div>
      {customers.isLoading ? <div className="p-8 text-center text-sm text-[#748077]">Carregando clientes…</div> : customers.data?.items.length ? <div className="overflow-x-auto"><table className="w-full min-w-[780px] text-left"><thead className="bg-[#f8faf7] text-[10px] font-bold uppercase tracking-[0.12em] text-[#7c8a80]"><tr><th className="px-5 py-3.5">Cliente</th><th className="px-5 py-3.5">Status</th><th className="px-5 py-3.5">Última compra</th><th className="px-5 py-3.5">Total investido</th><th className="px-5 py-3.5">Pontos</th><th className="px-5 py-3.5"></th></tr></thead><tbody>{customers.data.items.map(customer => <tr key={customer.id} className="border-t border-[#eef1ed] transition-colors hover:bg-[#fafcf9]"><td className="px-5 py-3.5"><div className="flex items-center gap-3"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#e9f2e4] text-[10px] font-bold text-[#466b4e]">{customer.name.slice(0,2).toUpperCase()}</div><div><p className="text-xs font-semibold text-[#26342a]">{customer.name}</p><p className="mt-0.5 text-[11px] text-[#7d897f]">{customer.phone || customer.email || "Sem contato"}</p></div></div></td><td className="px-5 py-3.5"><Status value={customer.status} /></td><td className="px-5 py-3.5 text-xs text-[#627066]">{date(customer.lastPurchaseAt)}</td><td className="px-5 py-3.5 text-xs font-semibold text-[#314839]">{money.format(Number(customer.totalSpent))}</td><td className="px-5 py-3.5 text-xs text-[#627066]">{number.format(customer.points)}</td><td className="px-5 py-3.5 text-right"><Button variant="ghost" onClick={() => navigate(`/app/clientes/${customer.id}`)} className="h-8 rounded-lg px-2 text-xs text-[#507357]">Ver perfil <ChevronRight className="ml-1 h-3.5 w-3.5" /></Button></td></tr>)}</tbody></table></div> : <Empty icon={Users} title="Sua base ainda está vazia" description="Cadastre o primeiro cliente para começar a classificar risco, criar relacionamento e medir recuperação." action={<Button onClick={() => setOpen(true)} className="rounded-xl bg-[#1a3021] text-xs">Cadastrar cliente</Button>} />}</div></div>;
}

function CustomerDialog({ open, setOpen }: { open: boolean; setOpen: (open: boolean) => void }) {
  const [form, setForm] = useState({ name: "", phone: "", email: "", notes: "", consentWhatsapp: false }); const utils = trpc.useUtils();
  const create = trpc.customers.create.useMutation({ onSuccess: () => { toast.success("Cliente cadastrado com sucesso."); setOpen(false); setForm({ name: "", phone: "", email: "", notes: "", consentWhatsapp: false }); utils.customers.list.invalidate(); utils.reports.overview.invalidate(); }, onError: e => toast.error(errorMessage(e)) });
  return <Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="h-10 rounded-xl bg-[#1a3021] px-4 text-xs hover:bg-[#2d4935]"><Plus className="mr-1.5 h-4 w-4" />Novo cliente</Button></DialogTrigger><DialogContent className="max-w-lg"><DialogHeader><DialogTitle>Novo cliente</DialogTitle><DialogDescription>Comece o histórico de relacionamento com dados que realmente serão usados.</DialogDescription></DialogHeader><div className="grid gap-4 py-3"><div className="grid gap-2"><Label>Nome completo</Label><Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Ex.: Marina Duarte" /></div><div className="grid gap-2 sm:grid-cols-2"><div className="grid gap-2"><Label>WhatsApp</Label><Input value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })} placeholder="(11) 99999-9999" /></div><div className="grid gap-2"><Label>E-mail</Label><Input type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} placeholder="marina@email.com" /></div></div><div className="grid gap-2"><Label>Observações</Label><Textarea value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} placeholder="Objetivos, preferências ou contexto importante." /></div><label className="flex items-center gap-2 text-xs text-[#536158]"><input checked={form.consentWhatsapp} onChange={e => setForm({ ...form, consentWhatsapp: e.target.checked })} type="checkbox" className="h-4 w-4 rounded border-[#bfc9be] accent-[#406c49]" />Possui consentimento para receber WhatsApp.</label></div><DialogFooter><Button variant="outline" className="rounded-xl" onClick={() => setOpen(false)}>Cancelar</Button><Button className="rounded-xl bg-[#1a3021]" disabled={create.isPending} onClick={() => create.mutate({ ...form, email: form.email || null, phone: form.phone || null, notes: form.notes || null })}>{create.isPending && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Cadastrar</Button></DialogFooter></DialogContent></Dialog>;
}

export function CustomerDetailPage() {
  const [, params] = useRoute("/app/clientes/:id"); const id = Number(params?.id); const detail = trpc.customers.detail.useQuery({ id }, { enabled: Number.isFinite(id) }); const utils = trpc.useUtils(); const [, navigate] = useLocation(); const [note, setNote] = useState("");
  const addNote = trpc.customers.addNote.useMutation({ onSuccess: () => { setNote(""); toast.success("Nota adicionada."); utils.customers.detail.invalidate({ id }); }, onError: e => toast.error(errorMessage(e)) }); const remove = trpc.customers.delete.useMutation({ onSuccess: () => { toast.success("Cliente excluído."); utils.customers.list.invalidate(); utils.reports.overview.invalidate(); navigate("/app/clientes"); }, onError: e => toast.error(errorMessage(e)) }); const purchase = trpc.customers.addPurchase.useMutation({ onSuccess: () => { toast.success("Compra registrada e cliente reativado."); utils.customers.detail.invalidate({ id }); utils.customers.list.invalidate(); utils.reports.overview.invalidate(); }, onError: e => toast.error(errorMessage(e)) });
  if (detail.isLoading) return <DashboardSkeleton />; if (!detail.data) return <div className="hl-page"><Button variant="ghost" onClick={() => navigate("/app/clientes")} className="mb-4">Voltar</Button><Empty icon={CircleAlert} title="Cliente não encontrado" description="Este cadastro não existe ou não pertence à organização atual." /></div>;
  const { customer, activities, openTasks, recovery } = detail.data;
  const recordPurchase = () => { const amount = window.prompt("Qual foi o valor da compra?", "0"); if (!amount) return; const parsed = Number(amount.replace(",", ".")); if (!Number.isFinite(parsed) || parsed <= 0) return toast.error("Informe um valor positivo."); purchase.mutate({ id, amount: parsed }); };
  const loyaltyUrl = `${window.location.origin}/pontos/${customer.loyaltyToken}`;
  return <div className="hl-page hl-fade-in"><button onClick={() => navigate("/app/clientes")} className="mb-5 text-xs font-semibold text-[#517457] hover:text-[#1d4427]">← Voltar para clientes</button><div className="flex flex-col gap-5 xl:flex-row xl:items-start xl:justify-between"><div className="flex items-center gap-4"><div className="grid h-14 w-14 place-items-center rounded-2xl bg-[#e2efd9] text-lg font-bold text-[#426747]">{customer.name.slice(0,2).toUpperCase()}</div><div><div className="flex flex-wrap items-center gap-2"><h1 className="text-2xl font-semibold tracking-[-0.05em] text-[#18221a]">{customer.name}</h1><Status value={customer.status} /></div><p className="mt-1 text-sm text-[#748077]">{customer.phone || "Sem telefone"} {customer.email ? `· ${customer.email}` : ""}</p></div></div><div className="flex flex-wrap gap-2"><CustomerEditDialog customer={customer} /><Button variant="outline" onClick={() => { if (window.confirm("Excluir este cliente e todos os dados relacionados? Esta ação não pode ser desfeita.")) remove.mutate({ id, reason: "Exclusão solicitada pelo gestor." }); }} disabled={remove.isPending} className="h-10 rounded-xl bg-white text-xs text-[#9b4848]"><Trash2 className="mr-1.5 h-4 w-4" />Excluir cliente</Button><Button variant="outline" onClick={recordPurchase} disabled={purchase.isPending} className="h-10 rounded-xl bg-white text-xs"><CircleDollarSign className="mr-1.5 h-4 w-4" />Registrar compra</Button><Button onClick={() => navigator.clipboard.writeText(loyaltyUrl).then(() => toast.success("Link do cartão copiado."))} className="h-10 rounded-xl bg-[#1a3021] text-xs">Copiar cartão de pontos</Button></div></div>
    <div className="mt-6 grid gap-5 xl:grid-cols-[1fr_0.78fr]"><div className="space-y-5"><div className="hl-card p-5"><div className="grid gap-4 sm:grid-cols-3"><Info label="Última compra" value={date(customer.lastPurchaseAt)} /><Info label="Total investido" value={money.format(Number(customer.totalSpent))} /><Info label="Pontos disponíveis" value={number.format(customer.points)} /></div></div><div className="hl-card p-5"><p className="text-sm font-semibold text-[#1b271e]">Linha do tempo</p><div className="mt-5 space-y-5">{activities.length ? activities.map(activity => <div key={activity.id} className="relative flex gap-3 pl-1"><span className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-[#86a860]" /><div><p className="text-xs font-medium text-[#354439]">{activity.content}</p><p className="mt-1 text-[10px] text-[#839087]">{dateTime(activity.createdAt)} {activity.amount ? `· ${money.format(Number(activity.amount))}` : ""}</p></div></div>) : <p className="py-4 text-xs text-[#7b887e]">O histórico aparecerá aqui conforme houver interações.</p>}</div><div className="mt-5 border-t border-[#edf0eb] pt-4"><Textarea value={note} onChange={e => setNote(e.target.value)} placeholder="Registrar uma nota de relacionamento…" className="min-h-[80px] text-xs" /><div className="mt-2 flex justify-end"><Button size="sm" disabled={!note.trim() || addNote.isPending} onClick={() => addNote.mutate({ id, content: note })} className="rounded-lg bg-[#1a3021] text-xs">Adicionar nota</Button></div></div></div></div>
      <div className="space-y-5"><div className="hl-card p-5"><p className="text-sm font-semibold text-[#1b271e]">Follow-ups em aberto</p><div className="mt-3 space-y-2">{openTasks.length ? openTasks.map(task => <div key={task.id} className="rounded-xl bg-[#f6f8f4] p-3"><p className="text-xs font-semibold text-[#314138]">{task.title}</p><div className="mt-1 flex items-center justify-between"><Status value={task.priority} /><span className="text-[10px] text-[#77847b]">{date(task.dueAt)}</span></div></div>) : <p className="py-4 text-xs text-[#7b887e]">Nenhum follow-up pendente.</p>}</div></div><div className="hl-card p-5"><div className="flex items-center justify-between"><p className="text-sm font-semibold text-[#1b271e]">Recuperação</p>{recovery && <Status value={recovery.status} />}</div>{recovery ? <div className="mt-4"><p className="text-xs text-[#6e7b72]">Potencial estimado</p><p className="mt-1 text-2xl font-semibold tracking-[-0.04em] text-[#284832]">{money.format(Number(recovery.potentialValue))}</p><p className="mt-3 text-[11px] text-[#7b887e]">{recovery.notes || "Sem observações neste caso."}</p></div> : <p className="mt-3 text-xs leading-5 text-[#78857b]">Este cliente ainda não está em uma jornada de recuperação.</p>}</div></div></div></div>;
}
function CustomerEditDialog({ customer }: { customer: { id: number; name: string; phone: string | null; email: string | null; notes: string | null; consentWhatsapp: boolean; pipelineStage: string } }) {
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ name: customer.name, phone: customer.phone || "", email: customer.email || "", notes: customer.notes || "", consentWhatsapp: customer.consentWhatsapp, pipelineStage: customer.pipelineStage });
  const utils = trpc.useUtils();
  const update = trpc.customers.update.useMutation({ onSuccess: () => { toast.success("Cliente atualizado."); setOpen(false); utils.customers.detail.invalidate({ id: customer.id }); utils.customers.list.invalidate(); }, onError: e => toast.error(errorMessage(e)) });
  useEffect(() => { setForm({ name: customer.name, phone: customer.phone || "", email: customer.email || "", notes: customer.notes || "", consentWhatsapp: customer.consentWhatsapp, pipelineStage: customer.pipelineStage }); }, [customer]);
  return <Dialog open={open} onOpenChange={setOpen}><Button variant="outline" onClick={() => setOpen(true)} className="h-10 rounded-xl bg-white text-xs"><Pencil className="mr-1.5 h-4 w-4" />Editar cliente</Button><DialogContent className="max-w-lg"><DialogHeader><DialogTitle>Editar cliente</DialogTitle><DialogDescription>Atualize os dados cadastrais e o consentimento de WhatsApp.</DialogDescription></DialogHeader><div className="grid gap-4 py-3"><div className="grid gap-2"><Label>Nome completo</Label><Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></div><div className="grid gap-2 sm:grid-cols-2"><div className="grid gap-2"><Label>WhatsApp</Label><Input value={form.phone} onChange={e => setForm({ ...form, phone: e.target.value })} /></div><div className="grid gap-2"><Label>E-mail</Label><Input type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} /></div></div><div className="grid gap-2"><Label>Observações</Label><Textarea value={form.notes} onChange={e => setForm({ ...form, notes: e.target.value })} /></div><label className="flex items-center gap-2 text-xs text-[#536158]"><input checked={form.consentWhatsapp} onChange={e => setForm({ ...form, consentWhatsapp: e.target.checked })} type="checkbox" className="h-4 w-4 accent-[#406c49]" />Possui consentimento para receber WhatsApp.</label></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={update.isPending || form.name.trim().length < 2} onClick={() => update.mutate({ id: customer.id, name: form.name, phone: form.phone || null, email: form.email || null, notes: form.notes || null, consentWhatsapp: form.consentWhatsapp, pipelineStage: form.pipelineStage as "new" | "contacted" | "interested" | "customer" | "recurring" })} className="bg-[#1a3021]">{update.isPending ? "Salvando…" : "Salvar alterações"}</Button></DialogFooter></DialogContent></Dialog>;
}

function Info({ label, value }: { label: string; value: string }) { return <div><p className="text-[10px] font-bold uppercase tracking-[0.12em] text-[#829087]">{label}</p><p className="mt-2 text-sm font-semibold text-[#2b3c30]">{value}</p></div>; }

export function TasksPage() { const tasks = trpc.tasks.list.useQuery(); const customerList = trpc.customers.list.useQuery(customerQuery); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ title: "", customerId: "", priority: "medium", dueAt: "" }); const create = trpc.tasks.create.useMutation({ onSuccess: () => { toast.success("Tarefa criada."); setOpen(false); setForm({ title: "", customerId: "", priority: "medium", dueAt: "" }); utils.tasks.list.invalidate(); }, onError: e => toast.error(errorMessage(e)) }); const done = trpc.tasks.complete.useMutation({ onSuccess: () => { toast.success("Tarefa concluída."); utils.tasks.list.invalidate(); utils.reports.overview.invalidate(); }, onError: e => toast.error(errorMessage(e)) }); return <div className="hl-page hl-fade-in"><PageHeader eyebrow="Execução" title="Follow-ups que não se perdem." description="Transforme a inteligência do sistema em contato humano no momento certo." action={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="h-10 rounded-xl bg-[#1a3021] text-xs"><Plus className="mr-1.5 h-4 w-4" />Nova tarefa</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Criar follow-up</DialogTitle><DialogDescription>Organize uma ação manual para um cliente ou para a equipe.</DialogDescription></DialogHeader><div className="grid gap-4 py-3"><div className="grid gap-2"><Label>Título</Label><Input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="Ex.: Ligar para entender objetivo" /></div><div className="grid gap-2"><Label>Cliente (opcional)</Label><Select value={form.customerId || "none"} onValueChange={value => setForm({ ...form, customerId: value === "none" ? "" : value })}><SelectTrigger><SelectValue placeholder="Sem cliente específico" /></SelectTrigger><SelectContent><SelectItem value="none">Sem cliente específico</SelectItem>{customerList.data?.items.map(c => <SelectItem key={c.id} value={String(c.id)}>{c.name}</SelectItem>)}</SelectContent></Select></div><div className="grid grid-cols-2 gap-3"><div className="grid gap-2"><Label>Prioridade</Label><Select value={form.priority} onValueChange={priority => setForm({ ...form, priority })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="low">Baixa</SelectItem><SelectItem value="medium">Média</SelectItem><SelectItem value="high">Alta</SelectItem></SelectContent></Select></div><div className="grid gap-2"><Label>Vencimento</Label><Input type="date" value={form.dueAt} onChange={e => setForm({ ...form, dueAt: e.target.value })} /></div></div></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={create.isPending} onClick={() => create.mutate({ title: form.title, customerId: form.customerId ? Number(form.customerId) : null, priority: form.priority as "low" | "medium" | "high", dueAt: form.dueAt ? new Date(`${form.dueAt}T12:00:00`) : null })} className="bg-[#1a3021]">Criar tarefa</Button></DialogFooter></DialogContent></Dialog>} />{tasks.isLoading ? <DashboardSkeleton /> : tasks.data?.length ? <div className="grid gap-3">{tasks.data.map(({ task, customer }) => <div key={task.id} className="hl-card flex items-center gap-4 p-4"><button onClick={() => done.mutate({ id: task.id })} className="grid h-6 w-6 shrink-0 place-items-center rounded-full border border-[#bdc9bc] text-transparent transition-colors hover:border-[#5d8c5d] hover:bg-[#e7f3dd] hover:text-[#477449]" aria-label="Concluir tarefa"><Check className="h-3.5 w-3.5" /></button><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-[#28372c]">{task.title}</p><p className="mt-1 text-xs text-[#76837a]">{customer?.name || "Tarefa geral"} {task.dueAt ? `· vence ${date(task.dueAt)}` : ""}</p></div><Status value={task.priority} /></div>)}</div> : <Empty icon={ClipboardCheck} title="Nada pendente por enquanto" description="Crie um follow-up manual ou deixe suas automações abrirem tarefas quando alguém entrar em risco." action={<Button onClick={() => setOpen(true)} className="rounded-xl bg-[#1a3021] text-xs">Criar follow-up</Button>} />}</div>; }

export function CrmPage() { const customers = trpc.customers.list.useQuery(customerQuery); const utils = trpc.useUtils(); const update = trpc.customers.update.useMutation({ onSuccess: () => { utils.customers.list.invalidate(); toast.success("Etapa atualizada."); }, onError: e => toast.error(errorMessage(e)) }); const stages = [{ id: "new", label: "Novo" }, { id: "contacted", label: "Em contato" }, { id: "interested", label: "Interessado" }, { id: "customer", label: "Cliente" }, { id: "recurring", label: "Recorrente" }] as const; return <div className="hl-page hl-fade-in"><PageHeader eyebrow="CRM" title="Relacionamento em movimento." description="Conduza cada pessoa da primeira conversa à recorrência." />{customers.isLoading ? <DashboardSkeleton /> : <div className="grid gap-4 xl:grid-cols-5">{stages.map(stage => { const cards = customers.data?.items.filter(customer => customer.pipelineStage === stage.id) ?? []; return <div key={stage.id} className="rounded-2xl border border-[#e4e9e3] bg-[#f1f4f0] p-3"><div className="mb-3 flex items-center justify-between px-1"><p className="text-xs font-bold text-[#506155]">{stage.label}</p><span className="grid h-5 min-w-5 place-items-center rounded-full bg-white px-1 text-[10px] font-bold text-[#77847b]">{cards.length}</span></div><div className="min-h-[180px] space-y-2">{cards.map(customer => <div key={customer.id} className="rounded-xl border border-[#e7ece5] bg-white p-3 shadow-sm"><div className="flex items-start justify-between gap-2"><p className="text-xs font-semibold text-[#29382d]">{customer.name}</p><Status value={customer.status} /></div><p className="mt-2 text-[10px] text-[#7b887e]">{money.format(Number(customer.totalSpent))} · {number.format(customer.points)} pts</p><Select value={customer.pipelineStage} onValueChange={pipelineStage => update.mutate({ id: customer.id, pipelineStage: pipelineStage as "new" | "contacted" | "interested" | "customer" | "recurring" })}><SelectTrigger className="mt-3 h-7 rounded-lg border-[#e8ece7] px-2 text-[10px]"><SelectValue /></SelectTrigger><SelectContent>{stages.map(destination => <SelectItem value={destination.id} key={destination.id}>{destination.label}</SelectItem>)}</SelectContent></Select></div>)}</div></div>; })}</div>}</div>; }

export function RecoveryPage() { const recovery = trpc.recovery.list.useQuery(); const utils = trpc.useUtils(); const sync = trpc.recovery.syncCandidates.useMutation({ onSuccess: result => { toast.success(`${result.count} clientes analisados para recuperação.`); utils.recovery.list.invalidate(); utils.reports.overview.invalidate(); }, onError: e => toast.error(errorMessage(e)) }); const update = trpc.recovery.update.useMutation({ onSuccess: () => { utils.recovery.list.invalidate(); utils.reports.overview.invalidate(); toast.success("Jornada de recuperação atualizada."); }, onError: e => toast.error(errorMessage(e)) }); const updateStatus = (id: number, status: "contacted" | "responded" | "recovered" | "lost") => { if (status === "recovered") { const value = window.prompt("Qual receita foi recuperada?", "0"); if (!value) return; const parsed = Number(value.replace(",", ".")); if (!Number.isFinite(parsed) || parsed <= 0) return toast.error("Informe uma receita positiva."); update.mutate({ id, status, recoveredValue: parsed }); } else update.mutate({ id, status }); }; return <div className="hl-page hl-fade-in"><PageHeader eyebrow="Recuperação" title="Receita que estava escapando." description="Priorize pessoas com maior potencial e registre o resultado financeiro de cada reativação." action={<Button onClick={() => sync.mutate()} disabled={sync.isPending} className="h-10 rounded-xl bg-[#1a3021] text-xs"><RefreshCw className={`mr-1.5 h-4 w-4 ${sync.isPending ? "animate-spin" : ""}`} />Encontrar oportunidades</Button>} />{recovery.isLoading ? <DashboardSkeleton /> : recovery.data?.length ? <div className="hl-card overflow-hidden"><div className="overflow-x-auto"><table className="w-full min-w-[860px] text-left"><thead className="bg-[#f8faf7] text-[10px] font-bold uppercase tracking-[0.12em] text-[#7c8a80]"><tr><th className="px-5 py-3.5">Cliente</th><th className="px-5 py-3.5">Última compra</th><th className="px-5 py-3.5">Potencial</th><th className="px-5 py-3.5">Jornada</th><th className="px-5 py-3.5">Ação</th></tr></thead><tbody>{recovery.data.map(({ recovery: item, customer }) => <tr key={item.id} className="border-t border-[#eef1ed]"><td className="px-5 py-3.5"><p className="text-xs font-semibold text-[#2b3a2f]">{customer.name}</p><p className="mt-1 text-[10px] text-[#7c897f]">{customer.phone || "Sem telefone"}</p></td><td className="px-5 py-3.5 text-xs text-[#637167]">{date(customer.lastPurchaseAt)}</td><td className="px-5 py-3.5 text-xs font-semibold text-[#31503a]">{money.format(Number(item.potentialValue))}</td><td className="px-5 py-3.5"><Status value={item.status} /></td><td className="px-5 py-3.5"><div className="flex gap-2">{item.status === "pending" && <Button size="sm" variant="outline" onClick={() => updateStatus(item.id, "contacted")} className="h-7 rounded-lg text-[10px]">Registrar contato</Button>}{item.status === "contacted" && <Button size="sm" variant="outline" onClick={() => updateStatus(item.id, "responded")} className="h-7 rounded-lg text-[10px]">Marcar resposta</Button>}{["pending", "contacted", "responded"].includes(item.status) && <Button size="sm" onClick={() => updateStatus(item.id, "recovered")} className="h-7 rounded-lg bg-[#3c7043] text-[10px]">Recuperou</Button>}</div></td></tr>)}</tbody></table></div></div> : <Empty icon={HeartHandshake} title="Nenhuma oportunidade de recuperação" description="Atualize a classificação de risco e use “Encontrar oportunidades” para abrir jornadas reais de reativação." action={<Button onClick={() => sync.mutate()} className="rounded-xl bg-[#1a3021] text-xs">Encontrar oportunidades</Button>} />}</div>; }

export function CampaignsPage() { const campaigns = trpc.campaigns.list.useQuery(); const whatsapp = trpc.campaigns.whatsappStatus.useQuery(); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ name: "", audience: "at_risk", message: "", templateName: "" }); const create = trpc.campaigns.create.useMutation({ onSuccess: () => { toast.success("Campanha salva como rascunho."); setOpen(false); setForm({ name: "", audience: "at_risk", message: "", templateName: "" }); utils.campaigns.list.invalidate(); }, onError: e => toast.error(errorMessage(e)) }); const dispatch = trpc.campaigns.dispatch.useMutation({ onSuccess: result => { toast.success(`${result.sentCount} mensagens enviadas; ${result.skippedCount} sem contato elegível.`); utils.campaigns.list.invalidate(); }, onError: e => toast.error(errorMessage(e)) }); const sendCampaign = (id: number) => { if (window.confirm("Confirmar disparo? A campanha será enviada apenas para clientes com consentimento e telefone válido.")) dispatch.mutate({ id }); }; return <div className="hl-page hl-fade-in"><PageHeader eyebrow="Comunicação" title="Campanhas com propósito." description="Fale com o público certo, respeite consentimento e acompanhe conversão." action={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="h-10 rounded-xl bg-[#1a3021] text-xs"><Plus className="mr-1.5 h-4 w-4" />Criar campanha</Button></DialogTrigger><DialogContent className="max-w-lg"><DialogHeader><DialogTitle>Nova campanha</DialogTitle><DialogDescription>O disparo usa somente templates aprovados na API oficial da Meta.</DialogDescription></DialogHeader><div className="grid gap-4 py-3"><div className="grid gap-2"><Label>Nome</Label><Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Ex.: Volta às aulas" /></div><div className="grid gap-2"><Label>Público</Label><Select value={form.audience} onValueChange={audience => setForm({ ...form, audience })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Toda a base consentida</SelectItem><SelectItem value="active">Clientes ativos</SelectItem><SelectItem value="at_risk">Clientes em risco</SelectItem><SelectItem value="inactive">Clientes inativos</SelectItem></SelectContent></Select></div><div className="grid gap-2"><Label>Template aprovado na Meta</Label><Input value={form.templateName} onChange={e => setForm({ ...form, templateName: e.target.value })} placeholder="Ex.: reativacao_agosto" /></div><div className="grid gap-2"><Label>Resumo interno da mensagem</Label><Textarea value={form.message} onChange={e => setForm({ ...form, message: e.target.value })} placeholder="Oferta, convite ou benefício da campanha." />{form.message.trim().length > 0 && form.message.trim().length < 3 && <p className="text-xs text-[#a13d3d]">Escreva pelo menos 3 caracteres.</p>}</div></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={create.isPending || form.name.trim().length < 3 || form.templateName.trim().length < 1 || form.message.trim().length < 3} onClick={() => create.mutate({ ...form, audience: form.audience as "all" | "active" | "at_risk" | "inactive", templateName: form.templateName.trim() || null })} className="bg-[#1a3021]">Salvar rascunho</Button></DialogFooter></DialogContent></Dialog>} />
    <div className={`mb-5 flex items-center gap-3 rounded-2xl border p-4 ${whatsapp.data?.configured ? "border-[#cde6c3] bg-[#f5fbf1]" : "border-[#f0dec0] bg-[#fffaf0]"}`}><div className={`grid h-9 w-9 place-items-center rounded-xl ${whatsapp.data?.configured ? "bg-[#dff3d6] text-[#3b713d]" : "bg-[#fff0d3] text-[#9a6811]"}`}><Send className="h-4 w-4" /></div><div><p className="text-xs font-semibold text-[#354439]">{whatsapp.data?.configured ? "WhatsApp Business conectado" : "WhatsApp Business ainda não conectado"}</p><p className="mt-0.5 text-[11px] text-[#7a877d]">{whatsapp.data?.configured ? "Disparos usam a Cloud API oficial da Meta." : "Crie campanhas agora; o disparo ficará liberado após inserir as credenciais oficiais no servidor."}</p></div></div>
    {campaigns.isLoading ? <DashboardSkeleton /> : campaigns.data?.length ? <div className="grid gap-3">{campaigns.data.map(campaign => <div key={campaign.id} className="hl-card flex flex-col gap-4 p-5 sm:flex-row sm:items-center"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#e6f0e2] text-[#4d754e]"><Megaphone className="h-4 w-4" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-semibold text-[#25342a]">{campaign.name}</p><Status value={campaign.status} /></div><p className="mt-1 truncate text-xs text-[#718075]">Público: {campaign.audience === "at_risk" ? "Em risco" : campaign.audience === "inactive" ? "Inativos" : campaign.audience === "active" ? "Ativos" : "Toda a base"} · Template: {campaign.templateName || "não definido"}</p></div><div className="grid grid-cols-3 gap-4 text-center"><MetricTiny label="Enviados" value={campaign.sentCount} /><MetricTiny label="Entregues" value={campaign.deliveredCount} /><MetricTiny label="Respostas" value={campaign.repliedCount} /></div><Button disabled={!whatsapp.data?.configured || dispatch.isPending || campaign.status === "sent"} onClick={() => sendCampaign(campaign.id)} className="h-9 rounded-xl bg-[#1a3021] text-xs">{campaign.status === "sent" ? "Enviada" : "Disparar"}</Button></div>)}</div> : <Empty icon={Megaphone} title="Nenhuma campanha criada" description="Crie um rascunho para organizar o público, a mensagem e o template aprovado antes do disparo." action={<Button onClick={() => setOpen(true)} className="rounded-xl bg-[#1a3021] text-xs">Criar campanha</Button>} />}</div>; }
function MetricTiny({ label, value }: { label: string; value: number }) { return <div><p className="text-sm font-semibold text-[#2f4134]">{number.format(value)}</p><p className="text-[9px] font-bold uppercase tracking-[0.1em] text-[#89958d]">{label}</p></div>; }

export function AutomationsPage() { const automations = trpc.automations.list.useQuery(); const runs = trpc.automations.runs.useQuery(); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ name: "", triggerValue: "30", actionType: "set_at_risk", taskTitle: "" }); const create = trpc.automations.create.useMutation({ onSuccess: () => { toast.success("Automação criada."); setOpen(false); setForm({ name: "", triggerValue: "30", actionType: "set_at_risk", taskTitle: "" }); utils.automations.list.invalidate(); }, onError: e => toast.error(errorMessage(e)) }); const run = trpc.automations.runNow.useMutation({ onSuccess: result => { toast.success(result.message); utils.automations.list.invalidate(); utils.automations.runs.invalidate(); utils.reports.overview.invalidate(); }, onError: e => toast.error(errorMessage(e)) }); const toggle = trpc.automations.toggle.useMutation({ onSuccess: () => utils.automations.list.invalidate(), onError: e => toast.error(errorMessage(e)) }); const schedule = trpc.automations.schedule.useMutation({ onSuccess: () => { toast.success("Automação agendada diariamente às 09:00 UTC."); utils.automations.list.invalidate(); }, onError: e => toast.error(errorMessage(e)) }); const unschedule = trpc.automations.unschedule.useMutation({ onSuccess: () => { toast.success("Agendamento removido."); utils.automations.list.invalidate(); }, onError: e => toast.error(errorMessage(e)) }); const labels: Record<string, string> = { set_at_risk: "marcar como Em risco", set_inactive: "marcar como Inativo", create_task: "criar tarefa de follow-up", queue_recovery: "adicionar à recuperação", award_points: "conceder pontos" }; return <div className="hl-page hl-fade-in"><PageHeader eyebrow="Automações" title="Regras que trabalham por você." description="Defina quando agir e mantenha todo evento registrado para auditoria." action={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="h-10 rounded-xl bg-[#1a3021] text-xs"><Plus className="mr-1.5 h-4 w-4" />Nova automação</Button></DialogTrigger><DialogContent className="max-w-lg"><DialogHeader><DialogTitle>Construir automação</DialogTitle><DialogDescription>Crie uma regra determinística, com logs e execução manual ou agendada.</DialogDescription></DialogHeader><div className="grid gap-4 py-3"><div className="grid gap-2"><Label>Nome da automação</Label><Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Ex.: Identificar alunos em risco" /></div><div className="rounded-xl bg-[#f5f8f3] p-3"><p className="text-[10px] font-bold uppercase tracking-[0.12em] text-[#728176]">Quando</p><div className="mt-2 flex items-center gap-2"><Input type="number" min="1" value={form.triggerValue} onChange={e => setForm({ ...form, triggerValue: e.target.value })} className="h-9 w-20 bg-white text-xs" /><span className="text-xs text-[#536158]">dias sem compra</span></div></div><div className="grid gap-2"><Label>Então</Label><Select value={form.actionType} onValueChange={actionType => setForm({ ...form, actionType })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{Object.entries(labels).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div>{form.actionType === "create_task" && <div className="grid gap-2"><Label>Título da tarefa</Label><Input value={form.taskTitle} onChange={e => setForm({ ...form, taskTitle: e.target.value })} placeholder="Ex.: Fazer contato por telefone" /></div>}</div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={create.isPending} onClick={() => create.mutate({ name: form.name, triggerType: "inactivity_days", triggerValue: Number(form.triggerValue), actionType: form.actionType as "set_at_risk" | "set_inactive" | "create_task" | "queue_recovery" | "award_points", actionConfig: form.taskTitle ? { taskTitle: form.taskTitle } : undefined })} className="bg-[#1a3021]">Criar automação</Button></DialogFooter></DialogContent></Dialog>} />
    <div className="grid gap-5 xl:grid-cols-[1fr_0.78fr]"><div>{automations.isLoading ? <DashboardSkeleton /> : automations.data?.length ? <div className="space-y-3">{automations.data.map(automation => <div key={automation.id} className="hl-card p-5"><div className="flex items-start gap-4"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#e5f2db] text-[#51784e]"><Bot className="h-4 w-4" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm font-semibold text-[#27362b]">{automation.name}</p><p className="mt-1 text-xs text-[#708075]">Quando ficar {automation.triggerValue} dias sem compra → {labels[automation.actionType]}</p></div><Switch checked={automation.enabled} onCheckedChange={enabled => toggle.mutate({ id: automation.id, enabled })} /></div><div className="mt-4 flex flex-wrap items-center gap-2"><Button size="sm" variant="outline" onClick={() => run.mutate({ id: automation.id })} disabled={run.isPending || !automation.enabled} className="h-8 rounded-lg text-[10px]"><RefreshCw className="mr-1 h-3 w-3" />Executar agora</Button><span className="text-[10px] text-[#809087]">{automation.lastRunAt ? `Última execução: ${dateTime(automation.lastRunAt)}` : "Ainda não executada"}</span>{automation.scheduleCronTaskUid ? <Button size="sm" variant="outline" onClick={() => unschedule.mutate({ id: automation.id })} disabled={unschedule.isPending} className="h-8 rounded-lg text-[10px]">Remover agenda</Button> : <Button size="sm" variant="outline" onClick={() => schedule.mutate({ id: automation.id, cron: "0 0 9 * * *" })} disabled={schedule.isPending || !automation.enabled} className="h-8 rounded-lg text-[10px]"><CalendarClock className="mr-1 h-3 w-3" />Agendar diariamente</Button>}{automation.scheduleCronTaskUid && <Badge variant="outline" className="border-[#cce3c4] text-[10px] text-[#3e743f]">Agendada</Badge>}</div></div></div></div>)}</div> : <Empty icon={Bot} title="Nenhuma regra criada" description="Comece pelas transições de risco ou gere tarefas de follow-up para a equipe." action={<Button onClick={() => setOpen(true)} className="rounded-xl bg-[#1a3021] text-xs">Criar automação</Button>} />}</div><div className="hl-card p-5"><div className="flex items-center gap-2"><CalendarClock className="h-4 w-4 text-[#527858]" /><p className="text-sm font-semibold text-[#25352a]">Registro de execuções</p></div><p className="mt-1 text-[11px] leading-4 text-[#77847b]">Cada regra gera um log com resultado e clientes afetados.</p><div className="mt-5 space-y-4">{runs.data?.length ? runs.data.slice(0,6).map(({ run: item, automation }) => <div key={item.id} className="border-l-2 border-[#d8ead2] pl-3"><p className="text-xs font-semibold text-[#415046]">{automation.name}</p><p className="mt-1 text-[11px] text-[#78857c]">{item.message}</p><p className="mt-1 text-[10px] text-[#919b93]">{dateTime(item.startedAt)}</p></div>) : <p className="py-8 text-center text-xs text-[#7d897f]">Os logs aparecerão aqui após a primeira execução.</p>}</div></div></div></div>; }

export function LoyaltyPage() { const loyalty = trpc.loyalty.overview.useQuery(); const utils = trpc.useUtils(); const [open, setOpen] = useState(false); const [form, setForm] = useState({ name: "", pointsCost: "100", couponCode: "" }); const create = trpc.loyalty.createReward.useMutation({ onSuccess: () => { toast.success("Recompensa criada."); setOpen(false); setForm({ name: "", pointsCost: "100", couponCode: "" }); utils.loyalty.overview.invalidate(); }, onError: e => toast.error(errorMessage(e)) }); const [, navigate] = useLocation(); return <div className="hl-page hl-fade-in"><PageHeader eyebrow="Fidelidade" title="Faça cada frequência valer mais." description="Crie recompensas, acompanhe pontos e compartilhe um cartão individual por QR Code." action={<Dialog open={open} onOpenChange={setOpen}><DialogTrigger asChild><Button className="h-10 rounded-xl bg-[#1a3021] text-xs"><Plus className="mr-1.5 h-4 w-4" />Nova recompensa</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Criar recompensa</DialogTitle><DialogDescription>Defina o benefício e quantos pontos são necessários para resgatá-lo.</DialogDescription></DialogHeader><div className="grid gap-4 py-3"><div className="grid gap-2"><Label>Nome</Label><Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Ex.: 1 aula extra" /></div><div className="grid gap-2"><Label>Pontos necessários</Label><Input type="number" min="1" value={form.pointsCost} onChange={e => setForm({ ...form, pointsCost: e.target.value })} /></div><div className="grid gap-2"><Label>Cupom (opcional)</Label><Input value={form.couponCode} onChange={e => setForm({ ...form, couponCode: e.target.value })} placeholder="FIT10" /></div></div><DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button onClick={() => create.mutate({ name: form.name, pointsCost: Number(form.pointsCost), couponCode: form.couponCode || null })} className="bg-[#1a3021]">Salvar recompensa</Button></DialogFooter></DialogContent></Dialog>} />
    {loyalty.isLoading ? <DashboardSkeleton /> : <><div className="grid gap-4 md:grid-cols-3"><MiniKpi label="Pontos distribuídos" value={number.format(loyalty.data?.distributed || 0)} hint="movimentação total registrada" /><MiniKpi label="Movimentações" value={number.format(loyalty.data?.transactions || 0)} hint="créditos e débitos auditáveis" tone="ink" /><MiniKpi label="Recompensas ativas" value={number.format(loyalty.data?.rewards.filter(r => r.active).length || 0)} hint="benefícios disponíveis" tone="amber" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[0.9fr_1.1fr]"><div className="hl-card p-5"><p className="text-sm font-semibold text-[#26352b]">Recompensas do programa</p><div className="mt-4 space-y-2">{loyalty.data?.rewards.length ? loyalty.data.rewards.map(reward => <div key={reward.id} className="rounded-xl bg-[#f5f8f3] p-3"><div className="flex justify-between gap-3"><p className="text-xs font-semibold text-[#34453a]">{reward.name}</p><span className="text-xs font-bold text-[#47734d]">{number.format(reward.pointsCost)} pts</span></div><p className="mt-1 text-[11px] text-[#77857b]">{reward.couponCode ? `Cupom: ${reward.couponCode}` : reward.description || "Sem cupom vinculado"}</p></div>) : <p className="py-8 text-center text-xs text-[#7c897f]">Crie a primeira recompensa do seu programa.</p>}</div></div><div className="hl-card p-5"><div className="flex items-center justify-between"><p className="text-sm font-semibold text-[#26352b]">Clientes com mais pontos</p><span className="text-[10px] font-bold uppercase tracking-[0.12em] text-[#839087]">Cartão individual</span></div><div className="mt-4 space-y-2">{loyalty.data?.topCustomers.length ? loyalty.data.topCustomers.map(customer => <div key={customer.id} className="flex items-center gap-3 rounded-xl border border-[#edf0eb] p-3"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#e7f1e2] text-[10px] font-bold text-[#486d4d]">{customer.name.slice(0,2).toUpperCase()}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold text-[#334238]">{customer.name}</p><p className="mt-0.5 text-[10px] text-[#7b887e]">{number.format(customer.points)} pontos</p></div><Button size="sm" variant="outline" onClick={() => navigate(`/app/fidelidade/${customer.id}`)} className="h-7 rounded-lg text-[10px]">QR Code</Button></div>) : <p className="py-8 text-center text-xs text-[#7c897f]">Os clientes aparecerão aqui quando forem cadastrados.</p>}</div></div></div></>}</div>; }

export function LoyaltyQrPage() { const [, params] = useRoute("/app/fidelidade/:id"); const id = Number(params?.id); const detail = trpc.customers.detail.useQuery({ id }, { enabled: Number.isFinite(id) }); const [, navigate] = useLocation(); if (detail.isLoading) return <DashboardSkeleton />; if (!detail.data) return <div className="hl-page"><Empty icon={CircleAlert} title="Cliente não encontrado" description="Não foi possível gerar o cartão de fidelidade." /></div>; const { customer } = detail.data; const url = `${window.location.origin}/pontos/${customer.loyaltyToken}`; return <div className="hl-page hl-fade-in"><button onClick={() => navigate("/app/fidelidade")} className="mb-5 text-xs font-semibold text-[#517457]">← Voltar para fidelidade</button><div className="mx-auto max-w-md"><div className="overflow-hidden rounded-[28px] bg-[#193021] p-7 text-center shadow-[0_24px_60px_rgba(20,42,28,.18)]"><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-[#b2cdaa]">Cartão de fidelidade</p><h1 className="mt-3 text-2xl font-semibold tracking-[-0.05em] text-white">{customer.name}</h1><div className="mt-6 rounded-2xl bg-[#d8ff70] px-5 py-4 text-[#183021]"><p className="text-[10px] font-bold uppercase tracking-[0.16em]">Saldo atual</p><p className="mt-1 text-3xl font-semibold tracking-[-0.06em]">{number.format(customer.points)} pts</p></div><div className="mx-auto mt-6 grid w-fit place-items-center rounded-2xl bg-white p-3"><QRCodeSVG value={url} size={154} bgColor="#ffffff" fgColor="#1a3021" level="M" includeMargin /></div><p className="mt-4 text-xs leading-5 text-[#b7cbb8]">Aponte a câmera para consultar pontos e recompensas disponíveis.</p></div><Button onClick={() => navigator.clipboard.writeText(url).then(() => toast.success("Link do cartão copiado."))} className="mt-4 h-10 w-full rounded-xl bg-[#1a3021] text-xs">Copiar link do cartão</Button></div></div>; }

export function ReportsPage() { const reports = trpc.reports.overview.useQuery(); const exports = trpc.reports.exportCustomers.useQuery(undefined, { enabled: false }); const download = async () => { const rows = await exports.refetch(); if (!rows.data?.length) return toast.error("Ainda não há clientes para exportar."); const csv = ["Nome;Telefone;E-mail;Status;Última compra;Total gasto;Pontos", ...rows.data.map(row => [row.name, row.phone || "", row.email || "", statusName[row.status], row.lastPurchaseAt ? new Date(row.lastPurchaseAt).toISOString().slice(0,10) : "", row.totalSpent, row.points].map(value => `\"${String(value).replaceAll('\"', '\"\"')}\"`).join(";"))].join("\n"); const blob = new Blob([csv], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "clientes-henderson-labs.csv"; anchor.click(); URL.revokeObjectURL(url); toast.success("Exportação iniciada."); }; return <div className="hl-page hl-fade-in"><PageHeader eyebrow="Inteligência" title="Resultado que cabe no relatório." description="Visualize carteira, recuperação e campanhas sem números decorativos." action={<Button onClick={download} disabled={exports.isFetching} variant="outline" className="h-10 rounded-xl bg-white text-xs"><Download className="mr-1.5 h-4 w-4" />Exportar clientes</Button>} />{reports.isLoading ? <DashboardSkeleton /> : reports.data ? <><div className="grid gap-4 md:grid-cols-3"><MiniKpi label="Receita total registrada" value={money.format(reports.data.metrics.totalRevenue)} hint="soma do histórico de compras" /><MiniKpi label="Receita recuperada" value={money.format(reports.data.metrics.recoveredRevenue)} hint="reativações confirmadas" tone="green" /><MiniKpi label="Taxa de recuperação" value={`${reports.data.metrics.inactive ? Math.round(reports.data.metrics.recovered / reports.data.metrics.inactive * 100) : 0}%`} hint="recuperados sobre inativos atuais" tone="amber" /></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><div className="hl-card p-5"><p className="text-sm font-semibold text-[#29392e]">Recuperação por etapa</p><div className="mt-5 space-y-3">{reports.data.recoveryPerformance.length ? reports.data.recoveryPerformance.map(row => <div key={row.status}><div className="mb-1.5 flex justify-between text-xs"><span className="text-[#647167]">{statusName[row.status]}</span><strong className="text-[#33463a]">{number.format(Number(row.count))} · {money.format(Number(row.revenue))}</strong></div><Progress value={reports.data.metrics.recovered ? Math.min(100, Number(row.count) / Math.max(1, reports.data.metrics.recovered) * 100) : 0} className="h-2" /></div>) : <p className="py-8 text-center text-xs text-[#7d897f]">Ainda não há jornadas de recuperação.</p>}</div></div><div className="hl-card p-5"><p className="text-sm font-semibold text-[#29392e]">Desempenho de campanhas</p><div className="mt-4 space-y-3">{reports.data.campaignPerformance.length ? reports.data.campaignPerformance.map(campaign => <div key={campaign.name} className="rounded-xl bg-[#f6f8f4] p-3"><div className="flex items-center justify-between"><p className="text-xs font-semibold text-[#35453a]">{campaign.name}</p><Status value={campaign.status} /></div><p className="mt-2 text-[11px] text-[#748177]">{campaign.sent} enviados · {campaign.delivered} entregues · {campaign.replied} respostas</p></div>) : <p className="py-8 text-center text-xs text-[#7d897f]">As campanhas aparecerão aqui quando criadas.</p>}</div></div></div></> : <Empty icon={CircleAlert} title="Relatórios indisponíveis" description="Tente atualizar esta página." />}</div>; }

export function SettingsPage() { const org = trpc.organization.current.useQuery(); const members = trpc.organization.members.useQuery(); const whatsapp = trpc.campaigns.whatsappStatus.useQuery(); const utils = trpc.useUtils(); const [form, setForm] = useState({ name: "", activeDays: "30", riskDays: "60" }); useEffect(() => { if (org.data) setForm({ name: org.data.organization.name, activeDays: String(org.data.organization.activeDays), riskDays: String(org.data.organization.riskDays) }); }, [org.data?.organization.id]); const update = trpc.organization.update.useMutation({ onSuccess: () => { toast.success("Configurações atualizadas."); utils.organization.current.invalidate(); }, onError: e => toast.error(errorMessage(e)) }); return <div className="hl-page hl-fade-in"><PageHeader eyebrow="Gestão" title="Configure seu laboratório." description="Personalize regras, equipe, plano e integrações sem expor informações sensíveis." />{org.isLoading ? <DashboardSkeleton /> : <div className="grid gap-5 xl:grid-cols-[1fr_0.9fr]"><div className="space-y-5"><div className="hl-card p-5"><div className="flex items-center gap-2"><Settings2 className="h-4 w-4 text-[#547a59]" /><p className="text-sm font-semibold text-[#2b3b30]">Organização e classificação</p></div><div className="mt-5 grid gap-4"><div className="grid gap-2"><Label>Nome do estabelecimento</Label><Input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></div><div className="grid grid-cols-2 gap-3"><div className="grid gap-2"><Label>Em risco após</Label><div className="relative"><Input type="number" min="1" value={form.activeDays} onChange={e => setForm({ ...form, activeDays: e.target.value })} /><span className="absolute right-3 top-2.5 text-xs text-[#7b887e]">dias</span></div></div><div className="grid gap-2"><Label>Inativo após</Label><div className="relative"><Input type="number" min="2" value={form.riskDays} onChange={e => setForm({ ...form, riskDays: e.target.value })} /><span className="absolute right-3 top-2.5 text-xs text-[#7b887e]">dias</span></div></div></div><Button onClick={() => update.mutate({ name: form.name, activeDays: Number(form.activeDays), riskDays: Number(form.riskDays) })} disabled={update.isPending} className="mt-1 w-fit rounded-xl bg-[#1a3021] text-xs">Salvar configurações</Button></div></div><div className="hl-card p-5"><div className="flex items-center justify-between"><div><p className="text-sm font-semibold text-[#2b3b30]">Equipe e permissões</p><p className="mt-1 text-[11px] text-[#7b887e]">Gestores administram, operadores executam e visualizadores leem.</p></div><Badge variant="outline" className="text-[10px]">{members.data?.length || 0} / {org.data?.limits.members || 0}</Badge></div><div className="mt-4 space-y-2">{members.data?.map(({ member, user }) => <div key={member.id} className="flex items-center gap-3 rounded-xl bg-[#f6f8f4] p-3"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#e2eedc] text-[10px] font-bold text-[#4d704f]">{user.name?.slice(0,2).toUpperCase() || "HL"}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold text-[#34443a]">{user.name || "Membro"}</p><p className="truncate text-[10px] text-[#7b887e]">{user.email}</p></div><Badge variant="outline" className="text-[10px] capitalize">{member.role}</Badge></div>)}</div></div></div><div className="space-y-5"><div className="rounded-2xl bg-[#1a3021] p-5 text-white"><p className="text-[10px] font-bold uppercase tracking-[0.16em] text-[#a9c2ae]">Plano atual</p><p className="mt-2 text-2xl font-semibold tracking-[-0.05em] capitalize">{org.data?.organization.plan === "professional" ? "Profissional" : org.data?.organization.plan}</p><p className="mt-3 text-xs leading-5 text-[#c0d0c2]">Até {number.format(org.data?.limits.customers || 0)} clientes, {number.format(org.data?.limits.automations || 0)} automações e {number.format(org.data?.limits.members || 0)} usuários.</p><PlanManager currentPlan={org.data?.organization.plan} /></div><PrivacyControls /><div className="hl-card p-5"><div className="flex items-center gap-2"><Send className="h-4 w-4 text-[#547a59]" /><p className="text-sm font-semibold text-[#2b3b30]">WhatsApp Business Cloud API</p></div><div className="mt-4 rounded-xl bg-[#f6f8f4] p-3"><p className="text-xs font-semibold text-[#3d503f]">{whatsapp.data?.configured ? "Integração configurada" : "Aguardando configuração"}</p><p className="mt-1 text-[11px] leading-5 text-[#77847b]">Use `WHATSAPP_ACCESS_TOKEN` e `WHATSAPP_PHONE_NUMBER_ID` exclusivamente no ambiente do servidor. O sistema envia templates aprovados pela Meta e registra entregas via webhook quando configurado.</p></div><a className="mt-4 inline-flex text-xs font-semibold text-[#47734d] hover:text-[#1e4729]" href="https://developers.facebook.com/documentation/business-messaging/whatsapp/get-started" target="_blank" rel="noreferrer">Ver guia oficial da Meta <ArrowUpRight className="ml-1 h-3.5 w-3.5" /></a></div></div></div>}</div>; }

export function PublicLoyaltyPage() { const [, params] = useRoute("/pontos/:token"); const token = params?.token || ""; const profile = trpc.loyalty.publicProfile.useQuery({ token }, { enabled: token.length >= 24 }); const [, navigate] = useLocation(); if (profile.isLoading) return <div className="grid min-h-screen place-items-center bg-[#f7f8f5]"><Loader2 className="h-6 w-6 animate-spin text-[#547a59]" /></div>; if (!profile.data) return <div className="grid min-h-screen place-items-center bg-[#f7f8f5] p-6"><div className="max-w-sm rounded-3xl bg-white p-8 text-center shadow-xl"><CircleAlert className="mx-auto h-8 w-8 text-[#bf5656]" /><h1 className="mt-4 text-xl font-semibold">Cartão não encontrado</h1><p className="mt-2 text-sm text-[#748077]">Peça um novo link ao seu estabelecimento.</p></div></div>; const { customer, rewards } = profile.data; return <div className="min-h-screen bg-[#f7f8f5] px-5 py-8 sm:py-14"><div className="mx-auto max-w-md"><div className="rounded-[28px] bg-[#1a3021] p-7 text-center text-white shadow-[0_28px_70px_rgba(20,42,28,.2)]"><p className="text-[10px] font-bold uppercase tracking-[0.2em] text-[#b4cdb6]">Henderson Labs</p><p className="mt-6 text-sm text-[#c6d6c7]">Olá, {customer.name}</p><p className="mt-2 text-5xl font-semibold tracking-[-0.07em] text-[#d8ff70]">{number.format(customer.points)}</p><p className="mt-1 text-xs font-semibold uppercase tracking-[0.15em] text-[#bfcec0]">pontos disponíveis</p></div><div className="mt-5 rounded-3xl bg-white p-6 shadow-[0_10px_40px_rgba(22,35,26,0.06)]"><p className="text-sm font-semibold text-[#27362b]">Recompensas disponíveis</p><div className="mt-4 space-y-2">{rewards.length ? rewards.map(reward => <div key={reward.id} className="flex items-center justify-between rounded-xl bg-[#f5f8f3] p-3"><div><p className="text-xs font-semibold text-[#35453a]">{reward.name}</p><p className="mt-1 text-[10px] text-[#7b887e]">{reward.couponCode ? `Cupom: ${reward.couponCode}` : reward.description || "Consulte as condições no estabelecimento."}</p></div><span className="text-xs font-bold text-[#47754c]">{number.format(reward.pointsCost)} pts</span></div>) : <p className="py-5 text-center text-xs text-[#7b887e]">Em breve, novas recompensas aparecerão aqui.</p>}</div></div><p className="mt-5 text-center text-[10px] text-[#8b978e]">Programa de fidelidade operado pelo seu estabelecimento.</p></div></div>; }
